//! Raw FFI bindings to [libsrt](https://github.com/Haivision/srt) (Secure
//! Reliable Transport).
//!
//! These are generated by `bindgen` at build time against a vendored, pinned
//! copy of libsrt (v1.5.4) built statically with mbedTLS. Everything here is
//! `unsafe`; the safe surface lives in the `srt` crate.
#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(dead_code)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));

#[cfg(test)]
mod tests {
    use super::*;

    /// Smoke test: the library links and its global init/teardown round-trips.
    #[test]
    fn startup_and_cleanup() {
        unsafe {
            assert!(srt_startup() >= 0, "srt_startup failed");
            // A freshly created socket should be a valid (non-invalid) handle.
            let sock = srt_create_socket();
            assert_ne!(sock, SRT_INVALID_SOCK, "srt_create_socket returned invalid");
            assert_eq!(srt_close(sock), 0, "srt_close failed");
            assert_eq!(srt_cleanup(), 0, "srt_cleanup failed");
        }
    }
}
